import{_ as t,o as d,c as o,a2 as c}from"./chunks/framework.Ch4PdLd_.js";const k=JSON.parse('{"title":"配置总览","description":"","frontmatter":{},"headers":[],"relativePath":"customize/configuration.md","filePath":"customize/configuration.md"}'),r={name:"customize/configuration.md"};function n(a,e,i,s,l,h){return d(),o("div",null,[...e[0]||(e[0]=[c('<h1 id="配置总览" tabindex="-1">配置总览 <a class="header-anchor" href="#配置总览" aria-label="Permalink to &quot;配置总览&quot;">​</a></h1><p>nek 的配置分为<strong>用户级</strong>和<strong>项目级</strong>两层：</p><ul><li>用户级数据在 <code>~/.nek/agent/</code>（可用环境变量 <code>NEK_CODING_AGENT_DIR</code> 改变，下文称“agent 目录”），对所有项目生效；</li><li>项目级配置在工作目录下的 <code>.nek/</code>，在<a href="/nekcode/guide/security#project-trust">信任项目</a>之后才加载。例外是 <code>sessionDir</code>，它在决定信任之前就会被读取，以便定位会话。</li></ul><p>交互模式下用 <code>/settings</code> 修改常用设置。手动修改设置、快捷键、指令文件或资源之后，运行 <code>/reload</code> 让当前会话生效。</p><h2 id="agent-dir" tabindex="-1">agent 目录（用户级） <a class="header-anchor" href="#agent-dir" aria-label="Permalink to &quot;agent 目录（用户级） {#agent-dir}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>路径</th><th>作用</th></tr></thead><tbody><tr><td><code>settings.json</code></td><td>用户级 <a href="/nekcode/reference/settings">设置</a></td></tr><tr><td><code>nek.yaml</code></td><td>nek 独有功能的配置：Plan、Todo、子代理，见 <a href="/nekcode/reference/nek-yaml">nek.yaml</a></td></tr><tr><td><code>keybindings.json</code></td><td>自定义 <a href="/nekcode/reference/keybindings">快捷键</a></td></tr><tr><td><code>models.json</code></td><td><a href="/nekcode/guide/models#compatible-endpoint">兼容接口、自定义模型和模型元数据覆盖</a></td></tr><tr><td><code>auth.json</code></td><td>保存的 API key 和 OAuth 凭据（<strong>勿外传</strong>）</td></tr><tr><td><code>mcp.json</code></td><td><a href="/nekcode/guide/mcp">MCP 服务器</a></td></tr><tr><td><code>mcp-auth.json</code></td><td>MCP 服务器的 OAuth 凭据</td></tr><tr><td><code>trust.json</code></td><td>保存的 <a href="/nekcode/guide/security#project-trust">项目信任</a> 决定</td></tr><tr><td><code>AGENTS.md</code>（或 <code>AGENTS.override.md</code>、<code>CLAUDE.md</code> 等）</td><td>对所有项目生效的 <a href="/nekcode/customize/context-files">指令</a></td></tr><tr><td><code>SYSTEM.md</code></td><td>替换默认系统提示词（nek 的一句身份说明仍保留在最前面）</td></tr><tr><td><code>APPEND_SYSTEM.md</code></td><td>追加到系统提示词末尾</td></tr><tr><td><code>agents/*.md</code></td><td>自定义 <a href="/nekcode/guide/subagents#custom-types">子代理类型</a></td></tr><tr><td><code>extensions/</code></td><td>自动加载的 <a href="/nekcode/customize/loading-extensions">扩展</a></td></tr><tr><td><code>skills/</code></td><td>用户级 <a href="/nekcode/customize/skills">Skills</a></td></tr><tr><td><code>prompts/</code></td><td>用户级 <a href="/nekcode/customize/prompt-templates">提示词模板</a></td></tr><tr><td><code>themes/</code></td><td>用户级 <a href="/nekcode/customize/themes">主题</a></td></tr><tr><td><code>sessions/</code></td><td>会话存储（可用 <code>sessionDir</code> 等改变，见 <a href="/nekcode/guide/sessions#storage">会话与上下文</a>）</td></tr><tr><td><code>bin/</code></td><td>自动下载的 fd、rg、ast-grep</td></tr><tr><td><code>mcp.log</code></td><td>MCP 服务器日志</td></tr><tr><td><code>nek-debug.log</code></td><td><code>/debug</code> 写出的诊断信息</td></tr></tbody></table><h2 id="project-dir" tabindex="-1">项目 <code>.nek</code> 目录 <a class="header-anchor" href="#project-dir" aria-label="Permalink to &quot;项目 `.nek` 目录 {#project-dir}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>路径</th><th>作用</th></tr></thead><tbody><tr><td><code>.nek/settings.json</code></td><td>项目级设置，覆盖用户级同名设置</td></tr><tr><td><code>.nek/nek.yaml</code></td><td>项目级 nek 配置</td></tr><tr><td><code>.nek/mcp.json</code></td><td>项目级 MCP 服务器</td></tr><tr><td><code>.nek/agents/*.md</code></td><td>项目级子代理类型</td></tr><tr><td><code>.nek/SYSTEM.md</code></td><td>替换本项目的系统提示词</td></tr><tr><td><code>.nek/APPEND_SYSTEM.md</code></td><td>追加本项目的系统提示词</td></tr><tr><td><code>.nek/extensions/</code></td><td>项目扩展</td></tr><tr><td><code>.nek/skills/</code></td><td>项目 Skills</td></tr><tr><td><code>.nek/prompts/</code></td><td>项目提示词模板</td></tr><tr><td><code>.nek/themes/</code></td><td>项目主题</td></tr><tr><td><code>.nek/plans/</code></td><td>Plan 模式写出的计划文件</td></tr></tbody></table><p>以上除 <code>plans/</code> 外都要在信任项目后才加载。项目里的 <code>AGENTS.md</code> 不在 <code>.nek/</code> 里，而是放在项目目录本身，见 <a href="/nekcode/customize/context-files">项目指令</a>。</p><h2 id="合并规则" tabindex="-1">合并规则 <a class="header-anchor" href="#合并规则" aria-label="Permalink to &quot;合并规则&quot;">​</a></h2><ul><li><strong>settings.json</strong>：项目设置覆盖用户设置；对象类型的设置（如 <code>compaction</code>）递归合并；资源列表（<code>skills</code>、<code>prompts</code> 等）合并。</li><li><strong>nek.yaml</strong>：先读用户级，再读项目级覆盖。</li><li><strong>mcp.json</strong>：项目里的同名服务器替换用户级的条目（只写开关字段时只覆盖开关）。</li><li><strong>agents/</strong>：同名时项目 &gt; 用户 &gt; 内置。</li><li>有几项只能在用户级设置：<code>defaultProjectTrust</code>、<code>httpProxy</code>、<code>cacheWarming</code>。</li></ul><h2 id="系统提示词文件" tabindex="-1">系统提示词文件 <a class="header-anchor" href="#系统提示词文件" aria-label="Permalink to &quot;系统提示词文件&quot;">​</a></h2><ul><li><code>SYSTEM.md</code> 整体替换默认的系统提示词。nek 会在它前面保留一句身份说明（“You are working inside nekcode, a terminal coding agent.”）。</li><li><code>APPEND_SYSTEM.md</code> 在系统提示词末尾追加内容。</li><li>项目级的同名文件作用于该项目。</li><li>命令行也能临时指定：<code>--system-prompt &lt;文本或文件&gt;</code>、<code>--append-system-prompt &lt;文本或文件&gt;</code>（可重复）。</li></ul><p>一般情况下优先用 <code>AGENTS.md</code> 写项目指令，它不会改动 nek 的基础提示词和工具说明。</p><h2 id="数据目录与-pi-的关系" tabindex="-1">数据目录与 pi 的关系 <a class="header-anchor" href="#数据目录与-pi-的关系" aria-label="Permalink to &quot;数据目录与 pi 的关系&quot;">​</a></h2><p>nek 使用独立的数据目录，不读取也不迁移 <code>~/.pi/</code> 里的数据。从 pi 迁移时，可以手动复制需要的文件（例如 <code>models.json</code>、<code>AGENTS.md</code>、<code>skills/</code>、<code>prompts/</code>、<code>themes/</code>），把项目里的 <code>.pi/</code> 改成 <code>.nek/</code>。凭据建议用 <code>/login</code> 重新登录。</p><h2 id="相关页面" tabindex="-1">相关页面 <a class="header-anchor" href="#相关页面" aria-label="Permalink to &quot;相关页面&quot;">​</a></h2><ul><li><a href="/nekcode/reference/settings">settings.json 参考</a></li><li><a href="/nekcode/reference/nek-yaml">nek.yaml 参考</a></li><li><a href="/nekcode/reference/environment-variables">环境变量</a></li><li><a href="/nekcode/customize/context-files">项目指令（AGENTS.md）</a></li></ul>',18)])])}const p=t(r,[["render",n]]);export{k as __pageData,p as default};
